/* Driver SK service worker. Generated by scripts/build-web.mjs; do not edit dist/sw.js by hand. */

const VERSION = '__VERSION__';
// eslint-disable-next-line no-undef
const PRECACHE = __PRECACHE__;
const CACHE_NAME = 'driver-sk-' + VERSION;
const INDEX = '/index.html';

// Precache everything the export produced, in chunks so one slow file
// does not stall the whole install.
self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const chunkSize = 25;
      for (let i = 0; i < PRECACHE.length; i += chunkSize) {
        await cache.addAll(PRECACHE.slice(i, i + chunkSize));
      }
      await self.skipWaiting();
    })()
  );
});

// Drop caches from previous versions and take over open pages.
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)));
      await self.clients.claim();
    })()
  );
});

const isNavigation = (request) =>
  request.mode === 'navigate' ||
  (request.method === 'GET' && (request.headers.get('accept') || '').includes('text/html'));

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // App shell: network first so deploys land, cached index.html when offline.
  if (isNavigation(request)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE_NAME);
        try {
          const fresh = await fetch(request);
          if (fresh && fresh.ok) await cache.put(INDEX, fresh.clone());
          return fresh;
        } catch {
          const cached = await cache.match(INDEX);
          return cached || new Response('Offline', { status: 503, statusText: 'Offline' });
        }
      })()
    );
    return;
  }

  // Everything else: cache first, then network, and remember what we fetched.
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(request, { ignoreSearch: true });
      if (cached) return cached;
      try {
        const fresh = await fetch(request);
        if (fresh && fresh.ok) await cache.put(request, fresh.clone());
        return fresh;
      } catch {
        return new Response('', { status: 504, statusText: 'Offline' });
      }
    })()
  );
});
